select from kb_routing_rule_targets rt left join kb_models m on rt.target_type = 'MODEL' and rt.target_id = m.id left join kb_model_pools mp on rt.target_type = 'MODEL_POOL' and rt.target_id = mp.id and mp.is_deleted = 0 left join kb_logical_models lm on lm.model_code = mp.logical_model_code and lm.is_deleted = 0 where rt.rule_id in
#{id}
order by rt.rule_id asc, rt.priority asc, rt.id asc
